/*!40000 ALTER TABLE `d_program_0` DISABLE KEYS */;
INSERT INTO `d_program_0` VALUES (2,2,1,2,1,1,'韦礼安「一直都在」音乐会','韦礼安','JDG英特尔电子竞技中心','https://s21.ax1x.com/2024/06/06/pkYEY9K.png',1,'本商品为预售商品，正式开票后将第一时间为您配票','预售期间，由于主办未正式开票，下单后无法立即为您配票。一般于演出前1-2周开票，待正式开票后，请您通过订单详情页或者票夹详情，查看票品信息、取票方式等演出相关信息','<div class=\"words\"><p><div style=\"text-align: left;\" data-spm-anchor-id=\"a2o7u.ssp_merchant_form.0.i211.1dfe106eT6n5Lp\"><strong data-spm-anchor-id=\"a2o7u.ssp_merchant_form.0.i8.1dfe106eW0Gc5h\">活动介绍</strong></div><div data-spm-anchor-id=\"a2o7u.ssp_merchant_form.0.i206.1dfe106eT6n5Lp\" style=\"text-align: center;\">韦礼安「一直都在」音乐见面会-北京站</div><p style=\"text-align: center;\" data-spm-anchor-id=\"a2o7u.ssp_reviewer_check.0.i1.8bd1106etyyPIZ\">是你的爱指引我未来<br>深深拥抱我的现在<br>告诉我原来爱一直都在</p><p style=\"text-align: center;\" data-spm-anchor-id=\"a2o7u.ssp_reviewer_check.0.i1.8bd1106etyyPIZ\"><img src=\"//img.alicdn.com/imgextra/i3/2251059038/O1CN019oiOfh2GdSYbtwJyA_!!2251059038.jpg_q60.jpg_.webp\" width=\"750\" height=\"1050\" ticketflow_width=\"750\" ticketflow_height=\"1050\"><br></p><p style=\"text-align: center;\" data-spm-anchor-id=\"a2o7u.ssp_merchant_form.0.i32.5e41106eGtOdMa\">时间：2024年1月13日（周六）20:00</p><p style=\"text-align: center;\" data-spm-anchor-id=\"a2o7u.ssp_merchant_form.0.i220.1dfe106eT6n5Lp\">地点：EAST &nbsp;LIVE（东郎展演中心）</p><p style=\"text-align: center;\" data-spm-anchor-id=\"a2o7u.ssp_merchant_form.0.i220.1dfe106eT6n5Lp\">地址：北京市朝阳区建国门外郎家园10号61幢1层A3-062层(印艺文创园内)</p><p style=\"text-align: center;\" data-spm-anchor-id=\"a2oeg.project.detail-info.i0.124a7445eFkOZ7\">票务信息</p><p style=\"text-align: center;\">VIP¥488</p><p style=\"text-align: center;\"><u><strong data-spm-anchor-id=\"a2o7u.ssp_merchant_form.0.i48.5e41106eOtr9fH\">（VIP权益：提前进场&amp;站前区&amp;巡演亲笔签名海报&amp;有机会获得与韦礼安合影机会）</strong></u></p><p style=\"text-align: center;\"><u><strong>备注：合影机会以现场抽签形式获得，限量6组，每组5人</strong></u></p><p style=\"text-align: center;\"><img src=\"//img.alicdn.com/imgextra/i4/2251059038/O1CN01dPeNja2GdSWgyxL8e_!!2251059038.jpg_q60.jpg_.webp\"><br></p><p style=\"text-align: center;\">普通票¥388</p><p style=\"text-align: center;\">早鸟票¥288</p><p style=\"text-align: center;\" data-spm-anchor-id=\"a2oeg.project.detail-info.i1.124a7445eFkOZ7\"><img src=\"//img.alicdn.com/imgextra/i2/2251059038/O1CN01HqkIcT2GdSWsaXgZi_!!2251059038.jpg_q60.jpg_.webp\"><br>韦礼安多首金曲：</p><p style=\"text-align: center;\">《一直都在》、《如果可以》、《女孩》、《慢慢等》、《有没有》、《狼》、《还是会》......</p><p style=\"text-align: center;\"><img src=\"//img.alicdn.com/imgextra/i1/2251059038/O1CN01JZWUQ32GdSWwCtU34_!!2251059038.jpg_q60.jpg_.webp\" data-spm-anchor-id=\"a2o7u.ssp_merchant_form.0.i18.49e9106epjZh8C\"></p><p style=\"text-align: center;\"><span data-spm-anchor-id=\"a2o7u.ssp_merchant_form.0.i19.49e9106epjZh8C\">出道以来韦礼安获奖无数，2011年凭借首张专辑获得金曲奖最佳新人奖的殊荣，</span><span>并在2015年以〈狼〉获得最佳作曲人奖。</span><span>创作才子韦礼安以阳光温暖的嗓音获得乐坛及歌迷的注目，长久累积丰沛的创作能</span><span>量，造就〈还是会〉、〈慢慢等〉等脍炙人口金曲， 「韦氏情歌」 更是知名偶</span><span>像剧必搭主题曲</span></p><p style=\"text-align: center;\"><span><img src=\"//img.alicdn.com/imgextra/i2/2251059038/O1CN014ooCq02GdSWt9wJYi_!!2251059038.jpg_q60.jpg_.webp\" data-spm-anchor-id=\"a2o7u.ssp_merchant_form.0.i208.1dfe106eT6n5Lp\"></span></p><p style=\"text-align: center;\">韦礼安「一直都在」音乐会，正在解锁更多城市中，这个冬天我们一起过，期待你的到来</p><p style=\"text-align: center;\" data-spm-anchor-id=\"a2o7u.ssp_merchant_form.0.i227.1dfe106ej4u8eV\">城市解锁中......</p><p><br></p></p></div>',6,6,'票品为有价票券，非普通商品，其背后承载的文化服务具有时效性，稀缺性等特征，不支持退换。','不支持修改配送电话、地址等信息','须打开【票夹】扫码入场，截图无效。','儿童一律凭票入场','演出开始前，去【订单详情页】提交发票申请。我们会将电子发票发送至您的邮箱。','一个订单对应一个证件；证件支持：护照/台湾居民来往大陆通行证/身份证/港澳居民来往内地通行证','对于异常订购行为，平台有权在订单成立或者生效之后取消相应订单。异常订购行为包括但不限于以下情形：（1）通过同一ID订购超出限购张数的订单。（2）经合理判断认为非真实消费者的下单行为，包括但不限于通过批量相同或虚构的支付账号、收货地址（包括下单时填写及最终实际收货地址）、收件人、电话号码订购超出限购张数的订单。','1.购买前请您提前规划好行程，做好相应准备，以免影响您的正常观演，感谢您的理解和配合。2.若演出受不可抗力影响延期或取消，平台将对演出票订单按照项目官方通知方案进行处理，其他因观演发生的费用需由您自行承担。','约90分钟，仅供参考，最终以现场实际时长为准','提前30-60分钟，仅供参考，最终以现场实际入场为准',NULL,'','','由于安保和版权的原因，大多数演出、展览及比赛场所禁止携带食品、饮料、专业摄录设备、打火机等物品，请您注意现场工作人员和广播的提示，予以配合。','以现场为准,以现场为准',NULL,0,'票品为有价票券，非普通商品，其背后承载的文化服务具有时效性，稀